            'titolo', 'descrizione', 'data_variante', 'updated_at'
        ]::text[]
    ) IS DISTINCT FROM (
        to_jsonb(OLD) - ARRAY[
            'titolo', 'descrizione', 'data_variante', 'updated_at'
        ]::text[]
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P2002',
            MESSAGE =
                'In bozza sono modificabili soltanto titolo, descrizione e data';
    END IF;

    RETURN NEW;
END;
$function$

