    OR to_char(current_row.data,'YYYY-MM-DD') IS DISTINCT FROM p_payload->>'data' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Rapportino/contesto non valido';
  END IF;
